// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;

    function setUp() public {
        c = new X_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 seed) public {
        address actor = address(uint160(uint256(keccak256(abi.encode(seed, "actor")))));
        uint256 minSum = c.MinSum();
        vm.deal(actor, minSum);

        // Set unlockTime in the past so Collect's time guard is satisfied.
        vm.warp(100);
        vm.prank(actor);
        c.Put{value: minSum}(1);

        ( , uint256 bal) = c.Acc(actor);
        uint256 balBefore = bal;

        vm.warp(200);
        vm.prank(actor);
        bool ok; try c.Collect(balBefore) { ok = true; } catch { ok = false; }

        ( , uint256 balAfter) = c.Acc(actor);

        assertTrue(balBefore == minSum ? (ok && balAfter < balBefore) : (balAfter <= balBefore));
    }
}
